suppressPackageStartupMessages(library(ggplot2))
args<-commandArgs(trailingOnly=TRUE)
out<-if(length(args))args[1] else 'outputs/diver_exclusion_refit_20261101'
a<-read.csv(if(length(args)>1)file.path(args[2],'pooled.csv') else 'outputs/pooled_common_estimand_20261101/pooled.csv');b<-read.csv(file.path(out,'pooled.csv'))
a<-subset(a,scenario=='Primary'&view=='All');b<-subset(b,scenario=='Primary'&view=='All')
x<-merge(a,b,by=c('metric','Taxa','Resp','view'),all=TRUE,suffixes=c('_previous','_audited'))
write.csv(x,file.path(out,'pooled_changes.csv'),row.names=FALSE)
a$version<-'Previous';b$version<-'Audited';z<-rbind(a,b)
labels<-c('M. pyrifera'='Kelp','M. franciscanus'='Red urchin','S. purpuratus'='Purple urchin','P. interruptus'='Lobster','S. pulcher'='Sheephead')
z$label<-paste(labels[z$Taxa],ifelse(z$Resp=='Bio','biomass','density'))
z$label<-factor(z$label,rev(c('Kelp biomass','Sheephead biomass','Lobster biomass','Red urchin biomass','Purple urchin biomass','Sheephead density','Lobster density','Red urchin density','Purple urchin density')))
z$metric<-factor(z$metric,c('Change','Post_difference'),labels=c('Before–after change','After-protection difference'))
z$version<-factor(z$version,c('Previous','Audited'));z$yy<-as.numeric(z$label)+ifelse(z$version=='Previous',.12,-.12)
z$precision<-ifelse(is.finite(z$low),'Interval','No reliable interval')
g<-ggplot(z,aes(estimate,yy,color=version))+geom_vline(xintercept=0,color='grey65',linetype='dashed')+geom_errorbar(aes(xmin=low,xmax=high),orientation='y',width=.12,linewidth=.65,na.rm=TRUE)+geom_point(aes(shape=precision),size=2.7)+scale_color_manual(values=c(Previous='#888888',Audited='#0072B2'))+scale_shape_manual(values=c(Interval=16,'No reliable interval'=1))+scale_y_continuous(breaks=seq_along(levels(z$label)),labels=levels(z$label),limits=c(.5,9.5))+facet_wrap(~metric,nrow=1)+labs(x='Log protected/reference ratio or change in that ratio',y=NULL)+theme_minimal(base_size=12)+theme(legend.position='none',panel.grid.minor=element_blank(),panel.grid.major.y=element_blank())
ggsave(file.path(out,'pooled_changes.png'),g,width=13,height=7,dpi=180);ggsave(file.path(out,'pooled_changes.pdf'),g,width=13,height=7)
